<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090b13"><title>LootZone | Admin</title><style>
:root{color-scheme:dark;--bg:#090b13;--panel:#121725;--line:#252d40;--muted:#9aa5bb;--text:#f4f6fb;--accent:#8b5cf6;--green:#22c55e;--yellow:#f59e0b;--red:#ef4444}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% 0,#211744 0,transparent 38%),var(--bg);color:var(--text);font-family:system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select{font:inherit}.wrap{max-width:1250px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:24px}.brand{display:flex;align-items:center;gap:12px}.logo{width:46px;height:46px;display:grid;place-items:center;border-radius:14px;background:linear-gradient(135deg,#8b5cf6,#06b6d4);font-weight:900}.muted{color:var(--muted)}.panel,.stat,.login{background:#121725eF;border:1px solid var(--line);border-radius:18px;box-shadow:0 12px 40px #0003}.stats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin-bottom:18px}.stat{padding:17px}.stat small{color:var(--muted)}.stat strong{display:block;font-size:27px;margin-top:8px}.toolbar{display:flex;gap:10px;flex-wrap:wrap;padding:14px;margin-bottom:14px}.toolbar input,.toolbar select,.login input{background:#0b1020;color:var(--text);border:1px solid var(--line);border-radius:11px;padding:11px 13px;min-width:170px;outline:none}.toolbar input{flex:1}.btn{border:0;border-radius:11px;padding:10px 15px;background:var(--accent);color:white;font-weight:700;cursor:pointer}.btn.secondary{background:#283149}.btn.danger{background:#7f1d1d}.tablebox{overflow:auto}.orders{width:100%;border-collapse:collapse;min-width:850px}.orders th,.orders td{text-align:right;padding:14px;border-bottom:1px solid var(--line);vertical-align:top}.orders th{color:var(--muted);font-size:12px;font-weight:600}.orders tr:last-child td{border:0}.code{font-weight:800;color:#c4b5fd}.status{display:inline-block;border-radius:99px;padding:5px 9px;font-size:12px;background:#78350f;color:#fde68a}.status.accepted{background:#164e63;color:#a5f3fc}.status.in_progress{background:#1e3a8a;color:#bfdbfe}.status.completed{background:#14532d;color:#bbf7d0}.status.cancelled{background:#7f1d1d;color:#fecaca}.copy{background:#283149;color:#dbeafe;border:0;border-radius:7px;padding:4px 8px;margin-inline-start:5px;cursor:pointer;font-size:11px}.detail{max-width:280px;white-space:normal;overflow-wrap:anywhere;line-height:1.8}.detail div{margin:2px 0}.status-select{background:#0b1020;color:white;border:1px solid var(--line);border-radius:8px;padding:7px}.login{max-width:390px;margin:10vh auto;padding:26px}.login h2{margin-top:0}.login input{display:block;width:100%;margin:12px 0}.hidden{display:none!important}.notice{margin:12px 0;color:#fca5a5;min-height:22px}.empty{text-align:center;padding:35px;color:var(--muted)}.actions{display:flex;align-items:center;gap:7px;flex-wrap:wrap}@media(max-width:850px){.stats{grid-template-columns:repeat(2,1fr)}.wrap{padding:14px}.top{align-items:flex-start}.stat:last-child{grid-column:span 2}}
</style></head><body><div class="wrap">
<section id="login" class="login"><div class="brand"><div class="logo">LZ</div><div><h2 style="margin:0">LootZone Admin</h2><small class="muted">لوحة إدارة الطلبات</small></div></div><form id="loginForm"><input id="username" autocomplete="username" placeholder="اسم المستخدم" required><input id="password" type="password" autocomplete="current-password" placeholder="كلمة المرور" required><button class="btn" style="width:100%">تسجيل الدخول</button></form><div id="loginError" class="notice"></div></section>
<section id="dashboard" class="hidden"><header class="top"><div class="brand"><div class="logo">LZ</div><div><b style="font-size:20px">LootZone Admin</b><div class="muted">إدارة ومتابعة الطلبات</div></div></div><div class="actions"><span class="muted" id="lastUpdate"></span><button class="btn secondary" id="refresh">تحديث</button><button class="btn danger" id="logout">خروج</button></div></header>
<div class="stats"><div class="stat"><small>كل الطلبات</small><strong id="sTotal">0</strong></div><div class="stat"><small>قيد المعالجة</small><strong id="sProcessing">0</strong></div><div class="stat"><small>تم قبولها</small><strong id="sAccepted">0</strong></div><div class="stat"><small>جارٍ التنفيذ</small><strong id="sProgress">0</strong></div><div class="stat"><small>مكتملة</small><strong id="sCompleted">0</strong></div><div class="stat"><small>ملغاة</small><strong id="sCancelled">0</strong></div></div>
<div class="panel toolbar"><input id="search" placeholder="ابحث برقم الطلب أو الاسم أو الإيميل أو ID..."><select id="filter"><option value="all">كل الحالات</option><option value="processing">في انتظار القبول</option><option value="accepted">تم قبول الطلب</option><option value="in_progress">قيد التنفيذ</option><option value="completed">مكتمل</option><option value="cancelled">أرشيف الطلبات الملغاة</option></select></div>
<div class="panel tablebox"><table class="orders"><thead><tr><th>الطلب</th><th>العميل والتواصل</th><th>تفاصيل الطلب</th><th>التاريخ</th><th>الحالة والإجراء</th></tr></thead><tbody id="rows"><tr><td colspan="5" class="empty">جارٍ تحميل الطلبات...</td></tr></tbody></table></div><p class="muted" style="font-size:12px">تُحدّث القائمة تلقائياً كل 20 ثانية. بيانات العملاء تظهر للأدمن المسجّل فقط.</p></section></div>
<script>
const API='api.php';let csrf='';let allOrders=[];let cancelledOrders=[];const $=id=>document.getElementById(id);const labels={processing:'في انتظار القبول',accepted:'تم قبول الطلب',in_progress:'قيد التنفيذ',completed:'مكتمل',cancelled:'ملغي'};
async function call(action,data={},method='POST'){const r=await fetch(API+(method==='GET'?'?action='+action:''),{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:method==='GET'?undefined:JSON.stringify({action,...data}),credentials:'same-origin'});const j=await r.json();if(!r.ok)throw new Error(j.error||'request_failed');return j}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function copyBtn(v){if(!v)return '';return `<button class="copy" data-copy="${esc(v)}">نسخ</button>`}
function linkContact(o){if(o.contact_method==='telegram'){let u=o.contact_value||'';let href=u.startsWith('@')?'https://t.me/'+encodeURIComponent(u.slice(1)):(/^https:\/\/t\.me\/[A-Za-z0-9_+\/-]+$/.test(u)?u:'');return href?`<a target="_blank" rel="noopener" href="${esc(href)}">فتح Telegram ↗</a>`:'Telegram — لا يوجد رابط مباشر';}let digits=(o.contact_value||'').replace(/[^0-9+]/g,'');return digits?`<a target="_blank" rel="noopener" href="https://wa.me/${digits.replace(/\D/g,'')}">فتح WhatsApp ↗</a>`:'WhatsApp'}
function render(){const term=$('search').value.trim().toLowerCase(),f=$('filter').value;const source=f==='cancelled'?cancelledOrders:allOrders;const list=source.filter(o=>(f==='all'||f==='cancelled'||o.status===f)&&(!term||[o.order_code,o.customer_name,o.email,o.contact_value,o.player_id,o.jawaker_id,o.service].join(' ').toLowerCase().includes(term)));$('rows').innerHTML=list.length?list.map(o=>`<tr><td><div class="code">${esc(o.order_code)}</div><small class="muted">#${esc(o.id)}</small><div style="margin-top:7px"><span class="status ${esc(o.status)}">${labels[o.status]||esc(o.status)}</span></div></td><td class="detail"><b>${esc(o.customer_name)}</b><div>📧 ${o.email?esc(o.email)+copyBtn(o.email):'<span class="muted">لا يوجد بريد</span>'}</div><div>☎️ ${esc(o.contact_value)}${copyBtn(o.contact_value)}</div><div>${linkContact(o)}</div></td><td class="detail"><b>${esc(o.service)}</b>${o.player_id?`<div>🆔 Player ID: ${esc(o.player_id)}${copyBtn(o.player_id)}</div>`:''}${o.jawaker_id?`<div>🆔 Jawaker ID: ${esc(o.jawaker_id)}${copyBtn(o.jawaker_id)}</div>`:''}${o.currency?`<div>💰 ${esc(o.total_due||o.amount)} ${esc(o.currency)}</div>`:''}${o.note?`<div>📝 ${esc(o.note)}</div>`:''}</td><td class="detail">${new Date(o.created_at).toLocaleString('ar-TN')}</td><td>${o.status==='cancelled'?'<span class="status cancelled">ملغي — أرشيف</span>':`<select class="status-select" data-status="${esc(o.order_code)}">${Object.entries(labels).filter(([k])=>k!=='cancelled').map(([k,v])=>`<option value="${k}" ${o.status===k?'selected':''}>${v}</option>`).join('')}</select>`}<div class="muted" style="font-size:11px;margin-top:7px">${o.telegram_notified?'تم إشعار Telegram':'إشعار Telegram غير مؤكد'}</div></td></tr>`).join(''):'<tr><td colspan="5" class="empty">لا توجد طلبات مطابقة</td></tr>';
 document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='تم النسخ';setTimeout(()=>b.textContent='نسخ',1200)}catch(e){prompt('انسخ النص:',b.dataset.copy)}});
 document.querySelectorAll('[data-status]').forEach(s=>s.onchange=async()=>{const old=allOrders.find(o=>o.order_code===s.dataset.status)?.status; s.disabled=true;try{await call('update_status',{order_code:s.dataset.status,status:s.value});await load()}catch(e){alert('تعذر تحديث الحالة: '+e.message);s.value=old}s.disabled=false});}
async function load(){const d=await call('bootstrap',{},'GET');if(!d.authenticated){$('dashboard').classList.add('hidden');$('login').classList.remove('hidden');return}csrf=d.csrf;allOrders=d.orders||[];cancelledOrders=d.cancelled_orders||[];const s=d.stats||{};$('sTotal').textContent=s.total||0;$('sProcessing').textContent=s.processing||0;$('sAccepted').textContent=s.accepted||0;$('sProgress').textContent=s.in_progress||0;$('sCompleted').textContent=s.completed||0;$('sCancelled').textContent=s.cancelled||0;$('lastUpdate').textContent='آخر تحديث: '+new Date().toLocaleTimeString('ar-TN');$('login').classList.add('hidden');$('dashboard').classList.remove('hidden');render()}
$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginError').textContent='';try{const d=await call('login',{username:$('username').value,password:$('password').value});csrf=d.csrf;$('password').value='';await load()}catch(err){$('loginError').textContent=err.message==='invalid_credentials'?'بيانات الدخول غير صحيحة':err.message}};
$('refresh').onclick=()=>load().catch(e=>alert(e.message));$('search').oninput=render;$('filter').onchange=render;$('logout').onclick=async()=>{try{await call('logout')}catch(e){}csrf='';$('dashboard').classList.add('hidden');$('login').classList.remove('hidden')};
load().catch(e=>{$('loginError').textContent=e.message});setInterval(()=>{if(!$('dashboard').classList.contains('hidden'))load().catch(()=>{})},20000);
</script></body></html>
